window.__votdWeek && window.__votdWeek({"week":"2028-08-07","reading":"Alma 43–52","days":[{"d":"2028-08-07","ref":"Alma 45:15","b":"Alma","c":45,"v":15,"he":"וַיְהִי אַחֲרֵי דִבֶּר אַלְמָא אֶת־הַדְּבָרִים הָאֵלֶּה לְהֵילָמָן וַיְבָרְכֵהוּ וְגַם אֶת־בָּנָיו הָאֲחֵרִים וַיְבָרֵךְ גַּם אֶת־הָאָרֶץ לְמַעַן הַצַּדִּיקִים׃","en":"And now it came to pass that after Alma had said these things to Helaman, he blessed him, and also his other sons; and he also blessed the earth for the righteous’ sake."},{"d":"2028-08-08","ref":"Alma 46:8","b":"Alma","c":46,"v":8,"he":"כֵּן נִרְאֶה מַה־מְּהֵרָה יִשְׁכְּחוּ בְּנֵי־הָאָדָם אֶת־יְהוָה אֱלֹהֵיהֶם אַף מַה־מְּהֵרָה לַעֲשׂוֹת רָע וּלְהִתְפַּתּוֹת לַמֵּסִית׃","en":"Thus we see how quick the children of men do forget the Lord their God, yea, how quick to do iniquity, and to be led away by the evil one."},{"d":"2028-08-09","ref":"Alma 46:12","b":"Alma","c":46,"v":12,"he":"וַיְהִי כִּי קָרַע אֶת־מְעִילוֹ וַיִּקַּח חֵלֶק מִמֶּנּוּ וַיִּכְתֹּב עָלָיו לְזִכְרוֹן אֱלֹהֵינוּ וְדָתֵנוּ וּדְרוֹרֵנוּ וּשְׁלוֹמֵנוּ נְשֵׁינוּ וּבָנֵינוּ וַיִּתְקַע אוֹתוֹ בִּקְצֵה הַמּוֹט׃","en":"And it came to pass that he rent his coat; and he took a piece thereof, and wrote upon it—In memory of our God, our religion, and freedom, and our peace, our wives, and our children—and he fastened it upon the end of a pole."},{"d":"2028-08-10","ref":"Alma 48:13","b":"Alma","c":48,"v":13,"he":"וְגַם הָיָה אִישׁ חָזָק בֶּאֱמוּנַת הַמָּשִׁיחַ וַיִּשָּׁבַע בִּשְׁבוּעָה לְהָגֵן עַל־עַמּוֹ וְעַל־מִשְׁפָּטָיו וְעַל־אַרְצוֹ וְעַל־דָּתוֹ עַד־שְׁפֹּךְ דָּמוֹ׃","en":"Yea, and he was a man who was firm in the faith of Christ, and he had sworn with an oath to defend his people, his rights, and his country, and his religion, even to the loss of his blood."},{"d":"2028-08-11","ref":"Alma 50:29","b":"Alma","c":50,"v":29,"he":"לָכֵן שָׂם מוֹרִיאַנְטוֹן בְּלִבָּם לָנוּס אֶל־הָאָרֶץ אֲשֶׁר מִצָּפוֹן אֲשֶׁר מְכֻסָּה בְּמִקְוֵי מַיִם גְּדוֹלִים וְלָרֶשֶׁת אֶת־הָאָרֶץ אֲשֶׁר מִצָּפוֹן׃","en":"Therefore, Morianton put it into their hearts that they should flee to the land which was northward, which was covered with large bodies of water, and take possession of the land which was northward."},{"d":"2028-08-12","ref":"Alma 52:9","b":"Alma","c":52,"v":9,"he":"וַיִּשְׁלַח אֵלָיו גַּם מִצְוֹת לְבַצֵּר אֶת־אֶרֶץ שֶׁפַע וְלִשְׁמֹר אֶת־הַמַּעֲבָר הַצַּר הַהֹלֵךְ אֶל־הָאָרֶץ מִצָּפוֹן פֶּן־יִירְשׁוּ הַלָּמָנִים אֶת־הַמָּקוֹם הַהוּא וְיוּכְלוּ לְהָצֵר לָהֶם מִכׇּל־עֵבֶר׃","en":"And he also sent orders unto him that he should fortify the land Bountiful, and secure the narrow pass which led into the land northward, lest the Lamanites should obtain that point and should have power to harass them on every side."},{"d":"2028-08-13","ref":"Alma 52:21","b":"Alma","c":52,"v":21,"he":"וַיְהִי כִּי מוֹרוֹנִי בְּאֵין תִּקְוָה לִפְגֹּשׁ אוֹתָם בְּמִישׁוֹר לָכֵן חָרַשׁ מְזִמָּה לְפַתּוֹת אֶת־הַלָּמָנִים מִמִּבְצְרֵיהֶם׃","en":"And it came to pass that Moroni, having no hopes of meeting them upon fair grounds, therefore, he resolved upon a plan that he might decoy the Lamanites out of their strongholds."}]});
